toolArgs.file_text:
.board-loading {
    text-align: center;
    padding: 2rem;
    color: #6b7280;
    font-size: 1.1rem;
}

.board-error {
    text-align: center;
    padding: 2rem;
    color: #dc2626;
    background: #fef2f2;
    border: 1px solid #fecaca;
    border-radius: 8px;
    margin: 1rem 0;
}

.board-error button {
    margin-top: 0.5rem;
    padding: 0.4rem 1rem;
    background: #dc2626;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

/* Stats bar */
.board-stats {
    display: flex;
    gap: 1rem;
    margin-bottom: 1rem;
    padding: 1rem;
    background: #f9fafb;
    border: 1px solid #e5e7eb;
    border-radius: 8px;
}

.stat {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 0.5rem 1rem;
    min-width: 80px;
}

.stat-value {
    font-size: 1.5rem;
    font-weight: 700;
    color: #111827;
}

.stat-label {
    font-size: 0.8rem;
    color: #6b7280;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.stat-overdue .stat-value {
    color: #dc2626;
}

/* Search bar */
.board-search {
    margin-bottom: 1rem;
}

.board-search input {
    width: 100%;
    padding: 0.6rem 1rem;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    font-size: 0.95rem;
    box-sizing: border-box;
}

/* Columns layout */
.board-columns {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.board-column {
    flex: 1;
    background: #f3f4f6;
    border-radius: 8px;
    padding: 1rem;
    min-height: 200px;
}

.column-header h3 {
    margin: 0 0 0.75rem;
    font-size: 1rem;
    color: #374151;
}

.column-count {
    color: #9ca3af;
    font-weight: 400;
}

.column-body {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

/* Task card */
.task-card {
    background: white;
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    padding: 0.75rem;
}

.task-title {
    margin: 0 0 0.25rem;
    font-size: 0.95rem;
    color: #111827;
}

.task-assignee {
    margin: 0 0 0.5rem;
    font-size: 0.85rem;
    color: #6b7280;
}

.priority-badge {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
}

.priority-high {
    background: #fef2f2;
    color: #dc2626;
}

.priority-medium {
    background: #fffbeb;
    color: #d97706;
}

.priority-low {
    background: #f0fdf4;
    color: #16a34a;
}

.task-due-date {
    margin-left: 0.5rem;
    font-size: 0.8rem;
    color: #6b7280;
}

.task-actions {
    display: flex;
    gap: 0.5rem;
    margin-top: 0.5rem;
}

.btn-move {
    padding: 0.25rem 0.5rem;
    font-size: 0.8rem;
    border: 1px solid #d1d5db;
    border-radius: 4px;
    background: white;
    cursor: pointer;
    color: #374151;
}

.btn-move:hover {
    background: #f3f4f6;
}

/* Add task */
.btn-add-task {
    width: 100%;
    margin-top: 0.75rem;
    padding: 0.5rem;
    background: transparent;
    border: 2px dashed #d1d5db;
    border-radius: 6px;
    color: #6b7280;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-add-task:hover {
    border-color: #9ca3af;
    color: #374151;
}

/* Add task form */
.add-task-form {
    margin-top: 0.75rem;
    padding: 0.75rem;
    background: white;
    border: 1px solid #d1d5db;
    border-radius: 6px;
}

.form-field {
    margin-bottom: 0.5rem;
}

.form-field label {
    display: block;
    font-size: 0.8rem;
    font-weight: 600;
    color: #374151;
    margin-bottom: 0.2rem;
}

.form-field input,
.form-field select {
    width: 100%;
    padding: 0.4rem 0.5rem;
    border: 1px solid #d1d5db;
    border-radius: 4px;
    font-size: 0.9rem;
    box-sizing: border-box;
}

.form-actions {
    display: flex;
    gap: 0.5rem;
    margin-top: 0.5rem;
}

.btn-save {
    padding: 0.4rem 0.75rem;
    background: #2563eb;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-save:hover {
    background: #1d4ed8;
}

.btn-save:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-cancel {
    padding: 0.4rem 0.75rem;
    background: white;
    border: 1px solid #d1d5db;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.85rem;
    color: #374151;
}

.btn-cancel:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

